OPJ_BOOL read_and_decode_rle4(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 y;
    OPJ_UINT8* row_start = pData;
    OPJ_UINT8* current_pixel;
    OPJ_UINT8 byte;
    OPJ_UINT32 bytes_per_row = (width + 1) / 2;  // RLE4 encodes 2 pixels per byte
    OPJ_UINT32 row_index = 0;

    for (y = 0; y < height; y++) {
        current_pixel = row_start + (y * stride);
        OPJ_UINT32 x = 0;

        while (x < width) {
            if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }

            if (byte == 0) {
                // Special cases or control codes
                fread(&byte, sizeof(OPJ_UINT8), 1, IN);
                if (byte == 0) {
                    // End of line
                    x = width;
                    continue;
                } else if (byte == 1) {
                    // End of bitmap
                    return (x == width) ? OPJ_TRUE : OPJ_FALSE;
                } else if (byte == 2) {
                    // Move to next row (skip)
                    row_index++;
                    row_start = pData + (row_index * stride);
                    x = width;
                    continue;
                } else {
                    // Absolute mode
                    OPJ_UINT32 abs_x;
                    fread(&abs_x, sizeof(OPJ_UINT32), 1, IN);
                    fread(&byte, sizeof(OPJ_UINT8), 1, IN);
                    if (abs_x < x) {
                        // Invalid absolute position
                        return OPJ_FALSE;
                    }

                    for (; x < abs_x && x < width; x += 2) {
                        current_pixel[x] = byte & 0x0F;
                        if (x + 1 < width) {
                            current_pixel[x + 1] = (byte >> 4) & 0x0F;
                        }
                    }
                }
            } else {
                // Encoded mode
                OPJ_UINT32 count = byte;
                OPJ_UINT32 i;
                for (i = 0; i < count && x < width; i++) {
                    if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                        return OPJ_FALSE;
                    }
                    current_pixel[x] = byte & 0x0F;
                    if (x + 1 < width) {
                        current_pixel[x + 1] = (byte >> 4) & 0x0F;
                    }
                    x += 2;
                }
            }
        }
    }

    return OPJ_TRUE;
}

OPJ_BOOL read_and_decode_rle4(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 y;
    OPJ_UINT8* row_ptr;
    OPJ_UINT8 byte;
    OPJ_BOOL encoded_mode = OPJ_TRUE;
    OPJ_UINT32 run_length;
    OPJ_UINT32 x = 0;

    for (y = 0; y < height; y++) {
        row_ptr = pData + y * stride;
        x = 0;

        while (x < width) {
            if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }

            if (byte == 0x00) {
                if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }

                if (byte == 0x00) {
                    if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1) {
                        return OPJ_FALSE;
                    }
                    if (byte == 0x00) {
                        // End of line
                        x = width;
                    } else {
                        // Move to next line
                        x = byte;
                        encoded_mode = OPJ_TRUE;
                    }
                } else {
                    // End of packet
                    return OPJ_TRUE;
                }
            } else {
                if (encoded_mode) {
                    run_length = (byte & 0xF0) >> 4;
                    row_ptr[x] = (byte & 0x0F) << 4;
                    x++;
                    if (run_length > 0) {
                        row_ptr[x] = (byte & 0x0F) << 4;
                        x++;
                        run_length--;
                    }

                    while (run_length > 0 && x < width) {
                        row_ptr[x] = row_ptr[x - 2];
                        x++;
                        run_length--;
                    }
                } else {
                    run_length = byte & 0x0F;
                    row_ptr[x] = (byte & 0xF0);
                    x++;
                    if (run_length > 0) {
                        row_ptr[x] = (byte & 0xF0);
                        x++;
                        run_length--;
                    }

                    while (run_length > 0 && x < width) {
                        row_ptr[x] = row_ptr[x - 2];
                        x++;
                        run_length--;
                    }
                }

                encoded_mode = !encoded_mode;
            }
        }
    }

    return OPJ_TRUE;
}

OPJ_BOOL decode_rle4_bitmap(FILE *IN, OPJ_UINT8 *pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT8 *row_ptr;
    OPJ_UINT32 row, col;
    OPJ_UINT8 pixel;
    OPJ_UINT8 count;
    OPJ_UINT8 cmd;

    for (row = 0; row < height; row++) {
        row_ptr = pData + (row * stride);
        col = 0;

        while (col < width) {
            if (fread(&cmd, sizeof(cmd), 1, IN) != 1)
                return OPJ_FALSE;

            if ((cmd & 0x80) != 0) {
                /* Encoded mode */
                count = cmd & 0x7F;
                pixel = 0;

                if (fread(&pixel, sizeof(pixel), 1, IN) != 1)
                    return OPJ_FALSE;

                while (count > 0 && col < width) {
                    row_ptr[col] = pixel;
                    col++;
                    count--;
                }
            } else {
                /* Absolute mode */
                count = cmd;

                while (count > 0 && col < width) {
                    if (fread(&pixel, sizeof(pixel), 1, IN) != 1)
                        return OPJ_FALSE;
                    row_ptr[col] = pixel;
                    col++;
                    count--;
                }
            }

            if (feof(IN))
                return OPJ_FALSE;
        }
    }

    return OPJ_TRUE;
}

OPJ_BOOL decode_rle4_bitmap(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT8* row_ptr = pData;
    OPJ_UINT32 y;
    OPJ_UINT8 count = 0;
    OPJ_UINT8 value = 0;
    OPJ_UINT8 run_length = 0;

    for (y = 0; y < height; y++) {
        OPJ_UINT8* pixel = row_ptr;
        OPJ_UINT32 x = 0;

        while (x < width) {
            if (feof(IN)) {
                return OPJ_FALSE;
            }

            if (count == 0) {
                if (fread(&count, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }
                if (count == 0) {
                    count = 1;
                }
                if (fread(&value, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }
                run_length = count;
            } else {
                run_length = count;
                if (fread(&value, sizeof(OPJ_UINT8), 1, IN) != 1) {
                    return OPJ_FALSE;
                }
            }

            while (run_length > 0 && x < width) {
                *pixel = value;
                pixel += 1;
                x += 1;
                run_length -= 1;
                count -= 1;
            }

            if (x >= width) {
                break;
            }

            if (feof(IN)) {
                return OPJ_FALSE;
            }

            if (fread(&count, sizeof(OPJ_UINT8), 1, IN) != 1) {
                return OPJ_FALSE;
            }

            if (count == 0) {
                count = 1;
            }
        }

        row_ptr += stride;
    }

    return OPJ_TRUE;
}

OPJ_BOOL decode_rle4_bitmap(FILE* IN, OPJ_UINT8* pData, OPJ_UINT32 stride, OPJ_UINT32 width, OPJ_UINT32 height) {
    OPJ_UINT32 row, col;
    OPJ_UINT8* pRow;
    OPJ_UINT8 byte, count, pixel, runValue;
    OPJ_BOOL runMode = OPJ_FALSE;

    for (row = 0; row < height; ++row) {
        pRow = pData + (row * stride);
        col = 0;
        while (col < width) {
            if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1)
                return OPJ_FALSE;

            if (byte == 0x00) {
                if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1)
                    return OPJ_FALSE;

                if (byte == 0x00) {
                    // End of line
                    break;
                } else if (byte == 0x01) {
                    // End of packet
                    break;
                } else if (byte == 0x02) {
                    // Move to next line
                    break;
                } else {
                    // Absolute mode
                    count = byte;
                    for (int i = 0; i < count && col < width; ++i) {
                        if (fread(&byte, sizeof(OPJ_UINT8), 1, IN) != 1)
                            return OPJ_FALSE;
                        pRow[col++] = byte;
                    }
                }
            } else {
                // Encoded mode
                if (!runMode) {
                    runValue = byte;
                    runMode = OPJ_TRUE;
                } else {
                    count = byte;
                    for (int i = 0; i < count && col < width; ++i) {
                        pRow[col++] = runValue;
                    }
                    runMode = OPJ_FALSE;
                }
            }
        }

        if (col < width) {
            // Fill remaining pixels with default value (0x00)
            while (col < width) {
                pRow[col++] = 0x00;
            }
        }
    }

    return OPJ_TRUE;
}
